pub const fn kled_p1(ctx: &Ctx) -> f32 {
    match ctx.level as u8 {
        ..=1 => 400f32,
        2 => 442.35,
        3 => 486.76,
        4 => 533.24,
        5 => 581.76,
        6 => 632.35,
        7 => 685f32,
        8 => 739.71,
        9 => 796.47,
        10 => 855.29,
        11 => 916.18,
        12 => 979.12,
        13 => 1044.12,
        14 => 1111.18,
        15 => 1180.29,
        16 => 1251.47,
        17 => 1324.71,
        18 => 1400f32,
        19 => 1477.35,
        20.. => 1556.76,
    }
}

pub const fn kled_p2(ctx: &Ctx) -> f32 {
    5f32 * (13f32 + 0.002 * ctx.bonus_health + ctx.level)
}

pub const fn kled_p3(ctx: &Ctx) -> f32 {
    0.025 * ctx.bonus_health
}

pub const fn kled_p4(ctx: &Ctx) -> f32 {
    5f32 * (13f32 + ctx.level)
}

pub const fn kled_p5(ctx: &Ctx) -> f32 {
    0.85 * ctx.bonus_armor
}

pub const fn kled_q1(ctx: &Ctx) -> f32 {
    60f32 + 1.2 * ctx.bonus_ad + 50f32 * (-1f32 + ctx.q_level)
}

pub const fn kled_q2(ctx: &Ctx) -> f32 {
    90f32 + 1.8 * ctx.bonus_ad + 75f32 * (-1f32 + ctx.q_level)
}

pub const fn kled_q3(ctx: &Ctx) -> f32 {
    63f32 + 1.17 * ctx.bonus_ad + 27f32 * (-1f32 + ctx.q_level)
}

pub const fn kled_q4(ctx: &Ctx) -> f32 {
    5f32 * (7f32 + 0.13 * ctx.bonus_ad + 3f32 * (-1f32 + ctx.q_level))
}

pub const fn kled_q5(ctx: &Ctx) -> f32 {
    7f32 + 0.13 * ctx.bonus_ad + 3f32 * (-1f32 + ctx.q_level)
}

pub const fn kled_w1(ctx: &Ctx) -> f32 {
    20f32
        + 10f32 * (-1f32 + ctx.w_level)
        + ctx.enemy_max_health
            * (0.045
                + 0.0002 * ctx.bonus_ad
                + 0.00004 * ctx.bonus_health
                + 0.005 * (-1f32 + ctx.w_level))
}

pub const fn kled_w2(ctx: &Ctx) -> f32 {
    2f32 * (31f32 + 8.13 * (-1f32 + ctx.level))
}

pub const fn kled_e1(ctx: &Ctx) -> f32 {
    5f32 * (7f32 + 0.11 * ctx.bonus_ad + 5f32 * (-1f32 + ctx.e_level))
}

pub const fn kled_e2(ctx: &Ctx) -> f32 {
    70f32 + 1.1 * ctx.bonus_ad + 50f32 * (-1f32 + ctx.e_level)
}

pub const fn kled_r1(ctx: &Ctx) -> f32 {
    0.0009 * ctx.bonus_ad
        + ctx.enemy_max_health * (0.12 + 0.03 * (-1f32 + ctx.r_level))
}

pub const fn kled_r2(ctx: &Ctx) -> f32 {
    0.0003 * ctx.bonus_ad
        + ctx.enemy_max_health * (0.04 + 0.01 * (-1f32 + ctx.r_level))
}

